/**
 * Which 40204 network this build is for.
 *
 * r1005 and r1006 share chain id 40204, so the chain id alone cannot tell them apart. Each
 * network has its own address book and chain constants, GENERATED by `pnpm sync-addresses` from
 * citrate-chain (scripts/sync-addresses.mjs); the constants carry the network name and its block-0
 * hash. `NEXT_PUBLIC_CITRATE_NETWORK` picks one at build time (web) and at start (indexer):
 *
 *   unset / "r1005"  → src/generated/{addresses,chainConstants}.json        (live until the cutover)
 *   "r1006"          → src/generated/r1006/{addresses,chainConstants}.json
 *
 * Any other value fails closed (throws) rather than falling back to a book for another chain.
 * The cutover switch is that one variable; see docs/R1006_CUTOVER.md.
 *
 * Data source (Rule 7): the generated files above (citrate-chain contracts/addresses/**, core/consensus
 * hardening.rs, core/economics genesis inputs). Nothing here reads the chain; the indexer and
 * /api/health compare the live RPC's block 0 against `genesisHash`.
 */
import r1005Book from "@/generated/addresses.json";
import r1005Constants from "@/generated/chainConstants.json";
import r1006Book from "@/generated/r1006/addresses.json";
import r1006Constants from "@/generated/r1006/chainConstants.json";

export const NETWORK_IDS = ["r1005", "r1006"] as const;
export type NetworkId = (typeof NETWORK_IDS)[number];

/** The network the explorer builds for when NEXT_PUBLIC_CITRATE_NETWORK is unset. */
export const DEFAULT_NETWORK: NetworkId = "r1005";

export interface ChainConstants {
  chainId: number;
  network: NetworkId;
  genesisHash: string;
  precompiles: { address: string; name: string; purpose: string; sources: string[] }[];
  genesisAllocations: { address: string; label: string; genesisSalt: string }[];
}

export interface AddressBook {
  chainId: number;
  contracts: Readonly<Record<string, string>>;
  aaStack: Readonly<Record<string, string>>;
  [k: string]: unknown;
}

export interface Network {
  id: NetworkId;
  book: AddressBook;
  constants: ChainConstants;
}

const NETWORKS: Record<NetworkId, Network> = {
  r1005: { id: "r1005", book: r1005Book as AddressBook, constants: r1005Constants as ChainConstants },
  r1006: { id: "r1006", book: r1006Book as AddressBook, constants: r1006Constants as ChainConstants },
};

/** The network for a NEXT_PUBLIC_CITRATE_NETWORK value. Unset/empty → r1005; unknown → throws. */
export function selectNetwork(value: string | undefined): Network {
  const id = value === undefined || value === "" ? DEFAULT_NETWORK : value;
  if (!(NETWORK_IDS as readonly string[]).includes(id)) {
    throw new Error(
      `NEXT_PUBLIC_CITRATE_NETWORK=${JSON.stringify(value)} is not a known 40204 network (${NETWORK_IDS.join(", ")})`,
    );
  }
  const n = NETWORKS[id as NetworkId];
  // The generated files must describe the network they are filed under.
  if (n.constants.network !== n.id || n.constants.chainId !== 40204 || n.book.chainId !== 40204) {
    throw new Error(`generated chain data for ${n.id} names ${n.constants.network} / chain ${n.constants.chainId}`);
  }
  return n;
}

/** The network this build is for. */
export const NETWORK: Network = selectNetwork(process.env.NEXT_PUBLIC_CITRATE_NETWORK);
export const ADDRESS_BOOK: AddressBook = NETWORK.book;
export const CHAIN_CONSTANTS: ChainConstants = NETWORK.constants;

/** `0xa365…cdd4`: enough of a block hash to tell two genesis blocks apart at a glance. */
export function shortGenesis(hash: string): string {
  return hash.length > 10 ? `${hash.slice(0, 6)}…${hash.slice(-4)}` : hash;
}

/** `r1006 · genesis 0xa365…cdd4`: the network name and genesis, for the UI. */
export function networkTag(c: Pick<ChainConstants, "network" | "genesisHash">): string {
  return `${c.network} · genesis ${shortGenesis(c.genesisHash)}`;
}
